"""Characterization of `render_topic_page` — the full markdown for a
fully-populated topic and for a topic with every section empty."""

from __future__ import annotations

from lib.topics.wiki import render_topic_page

_HEADER = ("Generated from `.regin/topics/topics/` + `topic.local.json` overlay. "
           "Do not edit this file as source of truth.")


def test_render_topic_page_full_and_bare():
    full = {
        "label": "Auth", "intent": "Log users in.", "aliases": ["login", "sso"],
        "refs": [{"path": "b.py", "role": "tests"}, {"path": "a.py"},
                 {"path": "c.py", "role": "docs"}],
        "commands": ["make auth"],
        "edges": [{"target": "db", "type": "depends_on"}, {"target": "ghost"}],
        "include_globs": ["src/auth/**"], "exclude_globs": ["**/*.snap"],
    }
    got = [
        render_topic_page("auth", full, {"db": {"label": "Database"}}),
        render_topic_page("bare", {}, {}),
    ]
    assert got == [FULL, BARE]


FULL = (
    f"# Auth\n\n{_HEADER}\n\n## Intent\n\nLog users in.\n\n"
    "## Aliases\n\n- `login`\n- `sso`\n\n"
    "## References\n\n### Implementation\n\n- `a.py`\n### Docs\n\n- `c.py`\n"
    "### Tests\n\n- `b.py`\n\n"
    "## Commands\n\n- `make auth`\n\n"
    "## Relationships\n\n- depends_on: `db` (Database)\n- related: `ghost` (ghost)\n\n"
    "## Globs\n\n### Include\n\n- `src/auth/**`\n\n### Exclude\n\n- `**/*.snap`\n"
)

BARE = (
    f"# bare\n\n{_HEADER}\n\n## Intent\n\n\n\n"
    "## Aliases\n\n- None\n\n"
    "## References\n\n- No approved refs.\n\n"
    "## Commands\n\n- None\n\n"
    "## Relationships\n\n- None\n\n"
    "## Globs\n\n### Include\n\n- None\n\n### Exclude\n\n- None\n"
)
